from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'evs','water-a-precious-gift','Water - A Precious Gift',
 ('Rain, rain, come again','What comes down but never goes up? Rain! We watch the sky for clues, collect rainwater and ask where it goes. Surya and Barkha follow the taps and pipes at home to find where the water comes from, and one day the water supply stops. This chapter is about how water reaches us, how we store and use it and how we should save it.'),
 [('Watching the rain',['We can guess if it will rain by watching clues such as dark clouds, cool wind and the smell of wet earth. Elders know many clues.','We can ask questions about the rain. Is it heavy or light? Are the raindrops big or small? Does it fall straight or slant in the wind?','Rain can make us happy, but a heavy rain can also trouble some people.']),
  ('Where the rainwater goes',['When it rains, water falls on different surfaces. On hard surfaces it flows away or dries up in the sun, and on soil much of it soaks in.','Water that soaks into the soil may slowly flow under the ground to a stream or pond. Some of it stays under the ground between the rocks and soil, and the water in our wells comes from this underground water.','Streams join rivers. Water also gathers in puddles, ponds and lakes, and flows to seas and oceans.','Rainwater that sinks into the soil is very important because it fills our water sources and helps plants grow.']),
  ('How water reaches our homes',['Water is a gift of nature. It reaches our taps through pipes from a tank, and the tank is filled from a bigger source such as a river, lake or well.','Some homes get water from a well or a borewell, drawn with a pulley, a hand pump or an electric pump.','Some people carry water from a river or a lake, and some get it from tankers. We should thank the people who bring us water.','Some families face difficulty in getting water every day.']),
  ('Storing and using water',['Water is used for drinking, cooking, bathing, washing, cleaning and watering plants.','When the supply stops, as it did for Surya and Barkha when the society pipeline burst, the water stored in buckets helps.','Long ago, there were no taps and pipes anywhere. People learned to make vessels to store water, such as clay pots, clay surahis, copper vessels and brass pots. Today we also use steel and aluminium pots, glass and plastic bottles and plastic buckets.','Used water becomes dirty and cannot be used for drinking or cooking, but it can be reused for watering plants or flushing toilets.','We should not add too much soap and other chemicals to water.']),
  ('Every drop counts',['Water is sacred because we cannot live without it. In some places it rains very little, and people walk long distances to get water.','Everyone should get clean drinking water anywhere, anytime.','We can offer clean water to those who come to our door, such as postal and sanitation workers. Many places keep pots of free drinking water outside homes in the hot months.','We can make a birdbath with a shallow wide container, stones for perching and fresh water, and change the water often.','We can save water by closing the tap, using only the water we need and reusing water for plants.'])],
 [('Where does the water in a well come from?',[('Rainwater soaks into the soil.','Water goes down into the ground.'),('Some of it stays between the rocks and soil as underground water.','This is the groundwater.'),('The well is dug to reach this water.','Water from the ground fills the well.')]),
  ('Give three ways to save water at home.',[('Close the tap while brushing the teeth.','No water is wasted.'),('Reuse the water used for washing vegetables for plants.','Reusing saves clean water.'),('Fix leaking taps.','A drip adds up to many litres.')])],
 ('Explain how rainwater reaches our taps and wells.',['Rain falls and soaks into the soil','Underground water fills wells','Rivers and lakes are sources','Pipes bring water to tanks and taps'],['Rain water comes from the tap','Water never needs saving']),
 ['Rain fills streams, rivers, ponds, lakes, wells and groundwater.','Water reaches our homes by pipes, wells, tankers or carrying.','We store water in vessels of many materials.','We should not waste water and should reuse it.','Every drop counts and everyone needs clean drinking water.'],
 [M('1',1,'What comes down but never goes up?','Rain',[('Sun','The sun is in the sky'),('Wind','Wind moves around')],'The riddle answer is rain.'),
  M('2',1,'Where does the water in a well come from?','Underground water',[('From the sky only','It comes from underground'),('From a shop','It is natural')],'Rainwater fills the ground.'),
  M('3',1,'Which of these is NOT a water source?','A road',[('River','A river is a source'),('Pond','A pond is a source')],'A road is not a source.'),
  M('4',1,'What fills the roof tank at Surya and Barkha\'s house?','Water brought through bigger pipes',[('Rain only','Pipes bring water'),('Nothing','It must be filled')],'It is filled from the supply.'),
  M('5',2,'What did Surya and Barkha use when the supply stopped?','Stored water in buckets',[('Rain','It was not raining'),('Milk','They used water')],'Stored water helped.'),
  M('6',2,'Which material is used to make a surahi?','Clay',[('Glass only','Clay surahi is traditional'),('Wood','Wood is not used')],'A clay surahi keeps water cool.'),
  M('7',2,'How can used water be reused?','To water plants',[('For drinking','It is dirty'),('For cooking','It is dirty')],'We can reuse waste water for plants and flushing.'),
  F('8',2,'Water that falls on hard surfaces soaks into the ground quickly.',False,'It flows away or dries in the sun.'),
  F('9',2,'Everyone should get clean drinking water.',True,'Water is essential for survival.'),
  M('10',2,'What do we put in a birdbath for birds to perch on?','Stones',[('Soap','Soap harms birds'),('Salt','Salt harms birds')],'Stones help birds to perch.'),
  S('11',3,'What is the underground storage of water called?',['groundwater','ground water'],'Groundwater fills wells.'),
  M('12',3,'Why is water called a precious gift?','We cannot live without it',[('It is always free everywhere','Some people must walk far for water'),('It is only for plants','All living things need water')],'Life needs water.')],
 keep=['groundwater','source','tank'])
